import assert from "node:assert/strict";
import { test } from "node:test";
import { toResource } from "../src/api.ts";
import { branchOf, byBranch, isUntagged, matches, toEnvResource } from "../src/filter.ts";
import type { EnvResource } from "../src/filter.ts";
import { buildPlan } from "../src/plan.ts";
import { summarize } from "../src/report.ts";

function resource(id: string, extra: Partial<EnvResource> = {}): EnvResource {
  return { id, type: "instance", name: id, tags: {}, stack_id: null,
    depends_on: [], cost_month_cents: 100, created_at: "2024-11-01T00:00:00Z", ...extra };
}

test("envctl preserves labels without changing the shared client's normalization", () => {
  const raw = { id: "cdk", labels: { Branch: "feat-ledger", Team: "payments" } };
  assert.deepEqual(toEnvResource(raw).labels, raw.labels);
  assert.equal(branchOf(toEnvResource(raw)), "feat-ledger");
  assert.equal("labels" in toResource(raw), false);
  assert.deepEqual(toEnvResource({ id: "legacy" }).labels, {});
});

test("label keys are case-insensitive, values are exact, and legacy tags take precedence", () => {
  for (const key of ["branch", "Branch", "BRANCH", "bRaNcH"]) {
    const r = resource("cdk", { labels: { [key]: "feat-ledger", Team: "payments" } });
    assert.equal(branchOf(r), "feat-ledger");
    assert.equal(isUntagged(r), false);
    assert.ok(matches(r, [["branch", "feat-ledger"], ["team", "payments"]]));
    assert.ok(!matches(r, [["branch", "FEAT-LEDGER"]]));
    assert.ok(!matches(r, [["missing", "value"]]));
    assert.equal(byBranch([r]).get("feat-ledger")?.length, 1);
    assert.doesNotMatch(summarize([r]), /untagged/);
  }
  const conflict = resource("conflict", { tags: { branch: "other" }, labels: { Branch: "feat-ledger" } });
  assert.equal(branchOf(conflict), "other");
  assert.equal(isUntagged(resource("none")), true);
});

test("plans include labels and stack companions but not other branches or similar stack names", () => {
  const resources = [
    resource("net", { tags: { branch: "feat-ledger" }, stack_id: "custom-stack" }),
    resource("boot", { stack_id: "custom-stack" }),
    resource("standard-boot", { stack_id: "stk-feat-ledger" }),
    resource("cdk", { labels: { Branch: "feat-ledger" }, depends_on: ["net", "boot"] }),
    resource("dns", { labels: { BRANCH: "feat-ledger" }, depends_on: ["cdk"] }),
    resource("other-label", { labels: { Branch: "other" }, stack_id: "stk-feat-ledger" }),
    resource("other-tag", { tags: { branch: "other" }, stack_id: "custom-stack" }),
    resource("prefix", { stack_id: "stk-feat-ledger-v2" }),
    resource("prefix-label", { labels: { Branch: "feat-ledger-v2" } }),
    resource("case-value", { labels: { Branch: "FEAT-LEDGER" } }),
    resource("orphan"),
  ];
  const plan = buildPlan(resources, "feat-ledger");
  assert.deepEqual(plan.steps.map((r) => r.id).sort(), ["boot", "cdk", "dns", "net", "standard-boot"]);
  assert.deepEqual(plan.blocked, []);
  const position = (id: string) => plan.steps.findIndex((r) => r.id === id);
  assert.ok(position("dns") < position("cdk"));
