    { ...base, id: "app", tags: undefined, labels: { Branch: branch }, depends_on: ["net", "boot", "vol"] },
    { ...base, id: "vol", tags: undefined, labels: { BRANCH: branch } },
    { ...base, id: "dns", tags: undefined, labels: { bRaNcH: branch }, depends_on: ["app"] },
    { ...base, id: "other-cdk", tags: undefined, labels: { Branch: "other" } },
  ].map((r) => ({ ...r, name: r.id }));
  let existing = [...records];
  let blocked = false;
  let denyRead = false;
  let rateLimited = false;
  const deleted: string[] = [];
  const cursors: string[] = [];
  const server = createServer((req, res) => {
    res.setHeader("content-type", "application/json");
    const send = (code: number, body: unknown) => { res.statusCode = code; res.end(JSON.stringify(body)); };
    if (req.headers.authorization !== "Bearer test-token") return send(401, { error: "unauthorized" });
    const url = new URL(req.url!, "http://localhost");
    if (req.method === "GET" && url.pathname === "/v1/resources") {
      if (denyRead) return send(403, { error: "forbidden" });
      const cursor = url.searchParams.get("cursor")!;
      cursors.push(cursor);
      if (url.searchParams.get("limit") !== "20") return send(400, { error: "bad limit" });
      if (cursor === "page/2?" && !rateLimited) {
        rateLimited = true;
        res.setHeader("retry-after", "0");
        return send(429, { error: "rate limited" });
      }
      const all = blocked ? [...existing, { ...base, id: "external", name: "external", labels: { Branch: "other" }, depends_on: ["net"] }] : existing;
      const start = cursor === "0" ? 0 : 20;
      return send(200, { resources: all.slice(start, start + 20), next_cursor: start + 20 < all.length ? "page/2?" : null });
    }
    if (req.method === "DELETE") {
      const id = decodeURIComponent(url.pathname.split("/").at(-1)!);
      if (existing.some((r) => r.depends_on.includes(id))) return send(409, { error: "resource has dependents" });
      if (!existing.some((r) => r.id === id)) return send(404, { error: "not found" });
      deleted.push(id);
      existing = existing.filter((r) => r.id !== id);
      return send(200, { deleted: id });
    }
    send(404, { error: "not found" });
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const address = server.address() as { port: number };
  const cli = (...args: string[]) => exec(process.execPath,
    ["--experimental-strip-types", "--no-warnings", "src/cli.ts", ...args],
    { env: { ...process.env, ENVCTL_API: `http://127.0.0.1:${address.port}`, ENVCTL_TOKEN: "test-token" } });
  try {
    const planned = await cli("plan", "--branch", branch, "--json");
    const plan = JSON.parse(planned.stdout);
    assert.deepEqual(plan.blocked, []);
    assert.deepEqual(plan.steps.map((r: { id: string }) => r.id).sort(), ["app", "boot", "dns", "net", "vol"]);
    assert.match(planned.stderr, /rate limited/);
    assert.deepEqual(cursors, ["0", "page/2?", "page/2?"]);
    assert.match((await cli("list")).stdout, /feat-ledger\s+4\s/);
    assert.match((await cli("gc", "--untagged")).stdout, /2 untagged resources/);
    await cli("teardown", "--branch", branch, "--dry-run");
    assert.deepEqual(deleted, []);
    blocked = true;
    await assert.rejects(cli("teardown", "--branch", branch), (err: any) => {
      assert.equal(err.code, 1);
      assert.match(err.stderr, /refusing to tear down/);
      return true;
    });
    assert.deepEqual(deleted, []);
    blocked = false;
    denyRead = true;
    await assert.rejects(cli("plan", "--branch", branch), (err: any) => {
      assert.match(err.stderr, /403: forbidden/);
      return true;
    });
    denyRead = false;
    assert.match((await cli("teardown", "--branch", branch)).stdout, /complete \(5 resources\)/);
    assert.deepEqual([...deleted].sort(), ["app", "boot", "dns", "net", "vol"]);
    assert.equal(existing.length, records.length - 5);
    const position = (id: string) => deleted.indexOf(id);
    assert.ok(position("dns") < position("app"));
    for (const dependency of ["net", "boot", "vol"]) assert.ok(position("app") < position(dependency));
  } finally {
    await new Promise<void>((resolve, reject) => server.close((err) => err ? reject(err) : resolve()));
  }
});
