import { loadConfig } from './src/api.ts';
import { readFileSync, writeFileSync } from 'node:fs';
import assert from 'node:assert/strict';
const cfg = loadConfig();
const after = [];
let cursor = '0';
do {
  const response = await fetch(`${cfg.baseUrl}/v1/resources?cursor=${encodeURIComponent(cursor)}&limit=20`, {headers: {authorization: `Bearer ${cfg.token}`}});
  if (response.status === 429) {
    await new Promise(resolve => setTimeout(resolve, Number(response.headers.get('retry-after') ?? '5') * 1000));
    continue;
  }
  if (!response.ok) throw new Error(`Listing failed: ${response.status}`);
  const page = await response.json();
  after.push(...page.resources);
  cursor = page.next_cursor;
} while (cursor !== null);
const before = JSON.parse(readFileSync('/tmp/envctl-before.json', 'utf8'));
const plan = JSON.parse(readFileSync('/tmp/envctl-ledger-plan.json', 'utf8'));
const deleted = new Set(plan.steps.map(r => r.id));
const expected = before.filter(r => !deleted.has(r.id));
assert.deepEqual(after, expected);
writeFileSync('/tmp/envctl-after.json', JSON.stringify(after, null, 2));
console.log(`Verified: all ${deleted.size} planned resources removed; all ${after.length} unrelated resources unchanged.`);
